  ...Object.entries(REQUEST_TEXTS).map(([kind, t3]) => ({ id: MAIN_TEXT.request(kind), page, group: REQUESTS, label: t3.label, note: "Fills {{what}} in a request's line.", text: t3.text, vars: [] })),
